            _check_finite_score(value, "sample_weight")
            if value < 0:
                raise ValueError(
                    "sample_weight must contain only finite non-negative "
                    "non-boolean numbers"
                )
        weights = [_roc_float(value) for value in sample_weight]

    pos_terms_total = []
